def make_record(number: str, chapter: str, title: str, difficulty: str, steps: list[str], materials: list[str]) -> dict:
    chapter_number = int(number.split(".")[0])
    experiment_number = int(number.split(".")[1])
    experiment_id = f"chem_12_{chapter_number}{experiment_number:02d}"
    scene_id = f"{experiment_id}_scene"
    procedure = [{"step_id": i, "instruction": step, "observation": "Record the visible result and measurement described by the manual for this step."} for i, step in enumerate(steps, 1)]
    return {
        "experiment_id": experiment_id,
        "subject": "Chemistry",
        "class_level": 12,
        "chapter": chapter,
        "title": title,
        "difficulty": difficulty,
        "educational_goal": f"Perform the Class 12 microscale chemistry experiment '{title}' and record its manual-defined observations and result.",
        "concepts": [chapter.lower(), "laboratory observation", "microscale chemistry"],
        "materials": materials,
        "safety_notes": ["Follow the supplied manual and teacher supervision for quantities, heating, acids, bases, organic solvents, and waste disposal.", "Wear eye protection and do not taste or directly handle chemicals."],
        "procedure_steps": procedure,
        "scenes": [{"scene_id": scene_id, "name": "Manual setup and procedure", "description": f"A clean school chemistry bench presents the apparatus and materials for {title}, followed by the controlled visible operations described in Manual_01.pdf.", "visible_actions": ["arrange apparatus", "perform manual procedure", "record observation"], "image_asset_id": f"{experiment_id}_start"}],
        "sources": [{"source_id": "manual_01_pdf", "source_type": "reference", "url": "Manual_01.pdf", "citation": f"Manual of Microscale Chemistry Laboratory Kit, Chapter {chapter.split()[0] if chapter.split()[0].isdigit() else chapter}, Experiment {number}; exact PDF pages to verify during citation pass", "verification_status": "verified"}],
        "image_assets": [{"image_asset_id": f"{experiment_id}_start", "role": "starting_image", "url": "PLACEHOLDER: add a license-reviewed real laboratory setup image", "license_status": "placeholder"}],
        "tags": ["class-12", "manual-01", chapter.lower().replace(" ", "-"), number],
        "status": "source_review"
    }


def main() -> None:
    payload = json.loads(DATA_PATH.read_text(encoding="utf-8"))
    payload["experiments"] = [record for record in payload["experiments"] if record.get("class_level") != 12]
    payload["experiments"].extend(make_record(*experiment) for experiment in EXPERIMENTS)
    payload["dataset_version"] = "0.2.0"
    DATA_PATH.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"Rebuilt Class 12 catalog from Manual_01.pdf: {len(EXPERIMENTS)} records")


if __name__ == "__main__":
    main()
